// El websocket-in avisa por su estado cuando se abre la conexión con el robot.
// Apenas se conecta hay que mandar el token (el robot cierra a los 5 s si no).
const s = msg.status || {};
const conectado = s.event === 'connect' ||
    (s.fill === 'green' && String(s.text || '').includes('connected'));
if (!conectado) return null;
const token = env.get('ROBOT_WS_TOKEN');
if (!token) {
    node.status({fill: 'red', shape: 'ring', text: 'falta ROBOT_WS_TOKEN'});
    return null;
}
flow.set('autenticado', false);
node.status({fill: 'yellow', shape: 'dot', text: 'enviando token'});
return {payload: 'T:' + token};

// Convierte cada mensaje del robot en una línea de InfluxDB (line protocol).
// Protocolo: docs/ind40/protocolo-websocket.md
const ROBOT = 'balancebot';
const txt = String(msg.payload || '').trim();
const p = txt.split(':');
const ts = Date.now();  // marca de tiempo de recepción (ms)
const int = (v) => Number.isFinite(Number(v)) ? Math.trunc(Number(v)) + 'i' : null;
const num = (v) => Number.isFinite(Number(v)) ? String(Number(v)) : null;

function linea(medida, campos) {
    const f = Object.entries(campos).filter(([, v]) => v !== null)
        .map(([k, v]) => k + '=' + v).join(',');
    return f ? `${medida},robot=${ROBOT} ${f} ${ts}` : null;
}

switch (p[0]) {
    case 'T':
        if (p[1] === 'OK') {
            flow.set('autenticado', true);
            node.status({fill: 'green', shape: 'dot', text: 'autenticado'});
        } else if (p[1] === 'ERR') {
            flow.set('autenticado', false);
            node.status({fill: 'red', shape: 'ring', text: 'token inválido'});
        }
        return null;
    case 'A':   // A:<angulo>:<velocidad>:<motores>
        if (p.length !== 4) return null;
        msg.payload = linea('telemetria', {
            angulo: num(p[1]), velocidad: int(p[2]), motores: int(p[3])});
        break;
    case 'E': { // E:<uptime_s>:<caidas>:<de_pie_s>:<bateria_mV>:<rssi>:<heap>:<clientes>
        if (p.length !== 8) return null;
        const bat = Number(p[4]);
        const rssi = Number(p[5]);
        msg.payload = linea('estado', {
            uptime_s: int(p[1]), caidas: int(p[2]), de_pie_s: int(p[3]),
            bateria_mv: bat >= 0 ? int(bat) : null,   // -1 = sin medición
            rssi_dbm: rssi !== 0 ? int(rssi) : null,  // 0 = STA no conectada
            heap_libre: int(p[6]), clientes: int(p[7])});
        node.status({fill: 'green', shape: 'dot',
            text: `uptime ${p[1]} s · caídas ${p[2]}`});
        break;
    }
    case 'F':   // F:<numero>:<angulo>:<tramo_ms>
        if (p.length !== 4) return null;
        msg.payload = linea('caida', {
            numero: int(p[1]), angulo: num(p[2]), tramo_ms: int(p[3])});
        break;
    default:
        return null;
}
return msg.payload ? msg : null;

// Junta las líneas y las escribe en InfluxDB de a lotes (cada 1 s o 500 líneas),
// en vez de una petición HTTP por cada mensaje de 10 Hz.
let buf = context.get('buf') || [];
if (msg.topic !== 'flush') {
    buf.push(msg.payload);
    context.set('buf', buf);
    if (buf.length < 500) return null;
}
if (buf.length === 0) return null;
context.set('buf', []);
const url = env.get('INFLUX_URL') || 'http://influxdb:8086';
return {
    method: 'POST',
    url: `${url}/api/v2/write?org=${encodeURIComponent(env.get('INFLUX_ORG'))}` +
         `&bucket=${encodeURIComponent(env.get('INFLUX_BUCKET'))}&precision=ms`,
    headers: {
        'Authorization': 'Token ' + env.get('INFLUX_TOKEN'),
        'Content-Type': 'text/plain; charset=utf-8'
    },
    payload: buf.join('\n'),
    lineas: buf.length
};

// InfluxDB responde 204 si la escritura salió bien.
if (msg.statusCode === 204) {
    node.status({fill: 'green', shape: 'dot',
        text: `${msg.lineas} líneas · ${new Date().toLocaleTimeString()}`});
    return null;
}
node.status({fill: 'red', shape: 'ring', text: `error ${msg.statusCode || ''}`});
node.warn(`InfluxDB respondió ${msg.statusCode}: ${typeof msg.payload === 'string' ? msg.payload : JSON.stringify(msg.payload)}`);
return null;
